//! `content.rs` — the file bodies the synthetic repository is made of.
//!
//! The corpus is not "a repo of empty files". A scenario that claims to contain a rename of a real module,
//! a test suite that got weaker, or a cycle between two layers has to contain those things as *text*, or
//! the ground-truth file is describing a fiction and every later ticket inherits the lie.
//!
//! So this module is a small library of plausible source files for a fictional Rust project (`lumen`, a
//! time-series renderer with a `core` → `store` → `api` layering, a web front end and a Python reporter).
//! Everything here is a pure function of its arguments, and every argument a scenario passes is a literal,
//! so the bytes are fixed. Where a scenario needs variation it passes a round number, and the function says
//! which lines that round changes — which is also what makes "the same region churned six times" a claim
//! the fixture can be checked against.
//!
//! Nothing here parses or analyses anything: a fixture that derived its own shape from an AST would be
//! halfway to certifying itself (ADR-002 §4.4).

/// A dependency line: `(crate, version, features)`.
pub type Dep<'a> = (&'a str, &'a str, &'a str);

/// `Cargo.toml` for the synthetic project.
#[must_use]
pub fn cargo_toml(deps: &[Dep<'_>]) -> String {
    let mut out = String::from(
        "[package]\nname = \"lumen\"\nversion = \"0.4.0\"\nedition = \"2024\"\nrust-version = \"1.97.0\"\n\n\
         [dependencies]\n",
    );
    for (name, version, features) in deps {
        if features.is_empty() {
            out.push_str(&format!("{name} = \"{version}\"\n"));
        } else {
            out.push_str(&format!(
                "{name} = {{ version = \"{version}\", features = [{features}] }}\n"
            ));
        }
    }
    out.push_str("\n[dev-dependencies]\ntempfile = \"3\"\n");
    out
}

/// The deps the first commit of most scenarios starts from.
#[must_use]
pub const fn baseline_deps() -> &'static [Dep<'static>] {
    &[
        ("serde", "1", "\"derive\""),
        ("serde_json", "1", ""),
        ("regex", "1.10.6", ""),
        ("thiserror", "2", ""),
    ]
}

/// `Cargo.lock`, from `(crate, version)` pairs, with the dependency edges implied by their order — enough
/// structure for a lockfile parser to have something true to find.
#[must_use]
pub fn cargo_lock(packages: &[(&str, &str)]) -> String {
    let mut out = String::from(
        "# This file is automatically @generated by Cargo.\n\
         # It is not intended for manual editing.\n\
         version = 4\n\n",
    );
    out.push_str("[[package]]\nname = \"lumen\"\nversion = \"0.4.0\"\n");
    if !packages.is_empty() {
        out.push_str("dependencies = [\n");
        for (name, version) in packages {
            out.push_str(&format!("  \"{name} {version}\",\n"));
        }
        out.push_str("]\n");
    }
    out.push('\n');
    for (name, version) in packages {
        out.push_str(&format!(
            "[[package]]\nname = \"{name}\"\nversion = \"{version}\"\nsource = \"registry+https://github.com/rust-lang/crates.io-index\"\nchecksum = \"{sum}\"\n\n",
            sum = checksum_for(name, version)
        ));
    }
    out
}

/// A stable fake checksum. It is not a real crates.io checksum and does not pretend to be one: it is a
/// deterministic 64-hex digest so that a lockfile looks like one and so that two lockfiles that differ only
/// in a version differ in bytes.
#[must_use]
pub fn checksum_for(name: &str, version: &str) -> String {
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for byte in name
        .bytes()
        .chain(std::iter::once(b'@'))
        .chain(version.bytes())
    {
        hash ^= u64::from(byte);
        hash = hash.wrapping_mul(0x100_0000_01b3);
    }
    let mut out = String::with_capacity(64);
    for round in 0..4 {
        let mut state = hash.rotate_left(round * 17) ^ (u64::from(round) << 32);
        for _ in 0..4 {
            state = state.wrapping_mul(0x9e37_79b9_7f4a_7c15).rotate_left(13);
            out.push_str(&format!("{:016x}", state));
        }
    }
    out.truncate(64);
    out
}

/// The ignore file, so a fixture can be `git status` clean while carrying sidecars.
#[must_use]
pub fn gitignore() -> String {
    "/target\n/fathom.sqlite\n/.fathom-cache\n".to_owned()
}

/// The README. `module` is the module the reader is told to start in, which is the line the rename scenarios
/// have to update — and therefore the line that proves a rename was really a rename.
#[must_use]
pub fn readme(module: &str) -> String {
    format!(
        "# lumen\n\n\
         A time-series renderer: `core` computes, `store` remembers, `api` answers questions.\n\n\
         Start in `{module}`.\n\n\
         ## Layout\n\n\
         * `src/core/` — the sample model and the downsampler\n\
         * `src/store/` — the segment store\n\
         * `src/api/` — the query surface\n\
         * `web/` — the browser front end\n\
         * `services/reporter/` — the nightly report job\n"
    )
}

/// `src/lib.rs`. Round 1 wires the api through `http`; the rename scenarios pass a different round because
/// the module they renamed is named here.
#[must_use]
pub fn lib_rs(module: &str) -> String {
    // The declaration list is assembled rather than written out as a literal, for two reasons. The round a
    // scenario is in decides which of these modules carries the renamed name, so one entry has to be a
    // parameter anyway; and ADR-002's R9 ("`pub mod` is declared in `lib.rs` only", lint `W4`) scans source text
    // for a line starting `pub mod`, cannot tell a declaration from a string that quotes one, and is right to
    // stay that way — so a fixture that *contains* a crate's lib.rs builds its copy out of pieces.
    let modules = ["core", "store", module, "parse", "render"];
    let mut out = String::new();
    for name in modules {
        out.push_str("pub mod ");
        out.push_str(name);
        out.push_str(";\n");
    }
    out.push_str(
        "\n\
         pub use core::Sample;\n\n\
         /// The one entry point the front ends call.\n\
         pub fn summarise(samples: &[Sample]) -> String {\n\
         \x20   let total: f64 = samples.iter().map(|s| s.value).sum();\n\
         \x20   format!(\"{} samples, {:.1} total\", samples.len(), total)\n\
         }\n",
    );
    out
}

/// The binary's `main`, so the project has an entry point.
#[must_use]
pub fn main_rs() -> String {
    "fn main() {\n    let samples = lumen::core::ramp(10);\n    println!(\"{}\", lumen::summarise(&samples));\n}\n".to_owned()
}

/// `src/core/mod.rs` — the bottom layer. `back_edge` adds the import that closes a cycle, which is the whole
/// point of `cycle_introduced`, so it is one deliberate line and nothing else.
#[must_use]
pub fn core_mod(back_edge: bool) -> String {
    let mut out = String::from(
        "/// One observation.\npub struct Sample {\n    pub at: i64,\n    pub value: f64,\n}\n\n\
         /// A ramp, for the demo and for the fixtures.\npub fn ramp(n: i64) -> Vec<Sample> {\n\
         \x20   (0..n)\n\
         \x20       .map(|i| Sample {\n\
         \x20           at: i * 1_000,\n\
         \x20           value: i as f64,\n\
         \x20       })\n\
         \x20       .collect()\n}\n\n\
         /// Downsample to at most `buckets` points, keeping the mean of each.\npub fn downsample(samples: &[Sample], buckets: usize) -> Vec<Sample> {\n\
         \x20   if buckets == 0 || samples.is_empty() {\n\
         \x20       return Vec::new();\n\
         \x20   }\n\
         \x20   let size = samples.len().div_ceil(buckets);\n\
         \x20   samples\n\
         \x20       .chunks(size.max(1))\n\
         \x20       .map(|chunk| {\n\
         \x20           let sum: f64 = chunk.iter().map(|s| s.value).sum();\n\
         \x20           Sample {\n\
         \x20               at: chunk[0].at,\n\
         \x20               value: sum / chunk.len() as f64,\n\
         \x20           }\n\
         \x20       })\n\
         \x20       .collect()\n}\n",
    );
    if back_edge {
        out.push_str(
            "\nuse crate::api::{self, Notice};\n\n\
             /// Tell the query surface that the model moved. Core should not know about this, and this is\n\
             /// the line that says it does.\n\
             pub fn notify(moved: i64) {\n\
             \x20   api::publish(Notice { moved });\n}\n",
        );
    }
    out
}

/// `src/store/mod.rs`. It is allowed to import `core`; `back_edge` makes it import `api` too, which is the
/// second cycle in `cycle_introduced`.
#[must_use]
pub fn store_mod(back_edge: bool) -> String {
    let mut out = String::from(
        "use crate::core::Sample;\n\n\
         /// One immutable run of samples.\npub struct Segment {\n    pub samples: Vec<Sample>,\n}\n\n\
         /// The in-memory store, one segment per flush.\n#[derive(Default)]\npub struct Store {\n\
         \x20   pub segments: Vec<Segment>,\n}\n\n\
         impl Store {\n\
         \x20   pub fn append(&mut self, samples: &[Sample]) {\n\
         \x20       self.segments.push(Segment {\n\
         \x20           samples: samples.to_vec(),\n\
         \x20       });\n\
         \x20   }\n\n\
         \x20   pub fn len(&self) -> usize {\n\
         \x20       self.segments.len()\n\
         \x20   }\n\n\
         \x20   pub fn is_empty(&self) -> bool {\n\
         \x20       self.segments.is_empty()\n\
         \x20   }\n}\n",
    );
    if back_edge {
        out.push_str(
            "\nuse crate::api::Notice;\n\nimpl Store {\n\
             \x20   /// Invalidate cached answers when the model moved. Again: the arrow points the wrong\n\
             \x20   /// way, and it is here so that the corpus contains the cycle, not just talks about it.\n\
             \x20   pub fn invalidate(&mut self, notice: &Notice) {\n\
             \x20       let _ = notice;\n\
             \x20       self.segments.clear();\n\
             \x20   }\n}\n",
        );
    }
    out
}

/// `src/api/mod.rs` — the top layer, which may import anything below it.
#[must_use]
pub fn api_mod(routes: &str) -> String {
    format!(
        "mod {routes};\n\n\
         pub use {routes}::query;\n\n\
         /// Something happened that invalidates answers.\npub struct Notice {{\n    pub moved: i64,\n}}\n\n\
         /// Publish a notice. The api is the only layer allowed to end a dependency chain.\n\
         pub fn publish(notice: Notice) {{\n\
         \x20   let _ = notice;\n}}\n"
    )
}

/// `src/api/routes.rs` (later `src/api/handlers.rs`, and later still `src/http/handlers.rs`).
#[must_use]
pub fn routes(body_round: u32) -> String {
    let extra = match body_round {
        0 => String::new(),
        1 => "\n/// The cache the query path reads. Round 1 of the feature.\n\
              #[derive(Default)]\npub struct Cache {\n    pub hits: u64,\n}\n"
            .to_owned(),
        _ => "\n/// The cache the query path reads, now with the miss counter the review asked for.\n\
              #[derive(Default)]\npub struct Cache {\n    pub hits: u64,\n    pub misses: u64,\n}\n\n\
              impl Cache {\n    pub fn hit_ratio(&self) -> f64 {\n        let total = self.hits + self.misses;\n\
              \x20   if total == 0 {\n            return 0.0;\n        }\n\
              \x20   self.hits as f64 / total as f64\n    }\n}\n"
            .to_owned(),
    };
    format!(
        "use crate::core::{data};\n\
         use crate::store::Store;\n\n\
         /// Answer a range query.\npub fn query(store: &Store, from: i64, to: i64) -> Vec<Sample> {{\n\
         \x20   store\n\
         \x20       .segments\n\
         \x20       .iter()\n\
         \x20       .flat_map(|segment| segment.samples.iter())\n\
         \x20       .filter(|sample| sample.at >= from && sample.at <= to)\n\
         \x20       .cloned()\n\
         \x20       .collect()\n}}\n{extra}",
        data = if body_round == 0 {
            "Sample"
        } else {
            "Sample, downsample"
        }
    )
}

/// `src/parse.rs`. Round 0 chokes on a trailing comma; round 1 tolerates it, which is the `fix` in
/// `scope_creep` and small enough that a reformat claim about it can be checked by eye.
#[must_use]
pub fn parse_rs(round: u32) -> String {
    let body = if round == 0 {
        "/// Parse one `name=value` pair per line.\npub fn parse(text: &str) -> Vec<(String, String)> {\n\
         \x20   text.lines()\n\
         \x20       .map(|line| {\n\
         \x20           let mut parts = line.split('=');\n\
         \x20           let name = parts.next().unwrap_or_default().to_owned();\n\
         \x20           let value = parts.next().unwrap_or_default().to_owned();\n\
         \x20           (name, value)\n\
         \x20       })\n\
         \x20       .collect()\n}\n"
    } else {
        "/// Parse one `name=value` pair per line.\n///\n\
         /// A trailing comma on a line used to drop the whole line, which is what the review caught.\n\
         pub fn parse(text: &str) -> Vec<(String, String)> {\n\
         \x20   text.lines()\n\
         \x20       .map(|line| line.trim().trim_end_matches(',').trim())\n\
         \x20       .filter(|line| !line.is_empty())\n\
         \x20       .map(|line| {\n\
         \x20           let mut parts = line.split('=');\n\
         \x20           let name = parts.next().unwrap_or_default().to_owned();\n\
         \x20           let value = parts.next().unwrap_or_default().to_owned();\n\
         \x20           (name, value)\n\
         \x20       })\n\
         \x20       .collect()\n}\n"
    };
    body.to_owned()
}

/// `src/render.rs`. Nothing depends on it except the front end, which is what makes touching it in a
/// parser fix a scope-creep signal.
#[must_use]
pub fn render_rs(round: u32) -> String {
    let width = if round == 0 { "60" } else { "80" };
    format!(
        "/// Draw one sample column per bucket.\npub fn sparkline(values: &[f64]) -> String {{\n\
         \x20   let max = values.iter().fold(0.0, |acc, v| if v > &acc {{ *v }} else {{ acc }});\n\
         \x20   let width = {width};\n\
         \x20   values\n\
         \x20       .iter()\n\
         \x20       .map(|v| {{\n\
         \x20           let filled = if max == 0.0 {{ 0 }} else {{ ((*v / max) * width as f64) as usize }};\n\
         \x20           \"#\".repeat(filled)\n\
         \x20       }})\n\
         \x20       .collect::<Vec<_>>()\n\
         \x20       .join(\"\\n\")\n}}\n"
    )
}

/// The core test suite. `tests` is how many survive: `test_deletion` walks it 5 → 3 → 2, and the deletion
/// of a named test is what the ground truth claims.
#[must_use]
pub fn tests_core(remaining: u32) -> String {
    let mut out = String::from("use lumen::core;\n\n");
    let all = [
        (
            "ramp_starts_at_zero",
            "#[test]\nfn ramp_starts_at_zero() {\n\
             \x20   let samples = core::ramp(4);\n\
             \x20   assert_eq!(samples[0].at, 0);\n\
             \x20   assert_eq!(samples.len(), 4);\n}\n",
        ),
        (
            "downsample_keeps_the_mean",
            "#[test]\nfn downsample_keeps_the_mean() {\n\
             \x20   let samples = core::ramp(10);\n\
             \x20   let buckets = core::downsample(&samples, 2);\n\
             \x20   assert_eq!(buckets.len(), 2);\n\
             \x20   assert!((buckets[0].value - 2.0).abs() < 0.01);\n}\n",
        ),
        (
            "downsample_of_empty_is_empty",
            "#[test]\nfn downsample_of_empty_is_empty() {\n\
             \x20   assert!(core::downsample(&[], 3).is_empty());\n\
             \x20   assert!(core::downsample(&core::ramp(3), 0).is_empty());\n}\n",
        ),
        (
            "epoch_round_trip",
            "#[test]\nfn epoch_round_trip() {\n\
             \x20   let samples = core::ramp(1_000);\n\
             \x20   let last = samples.last().expect(\"a ramp of 1000 is not empty\");\n\
             \x20   assert_eq!(last.at, 999_000);\n\
             \x20   assert!((last.value - 999.0).abs() < f64::EPSILON);\n}\n",
        ),
        (
            "timing_is_monotonic",
            "#[test]\nfn timing_is_monotonic() {\n\
             \x20   let samples = core::ramp(50);\n\
             \x20   for pair in samples.windows(2) {\n\
             \x20       assert!(pair[1].at > pair[0].at, \"clock went backwards\");\n\
             \x20   }\n}\n",
        ),
    ];
    for (index, (_, body)) in all.iter().enumerate().take(remaining as usize) {
        out.push_str(body);
        if index + 1 < remaining as usize {
            out.push('\n');
        }
    }
    out
}

/// One test, skipped rather than deleted — the shape `test_deletion`'s weakening claim is about.
#[must_use]
pub fn tests_core_ignored(remaining: u32) -> String {
    let mut out = String::new();
    for name in 0..remaining {
        out.push_str(&format!(
            "#[test]\n#[ignore = \"flaky on the shared runner, see the review\"]\n\
             fn kept_{name}() {{\n\x20   assert!(lumen::core::ramp({}).len() > {name});\n}}\n\n",
            name + 2
        ));
    }
    out
}

/// `tests/api.rs` — deleted whole by one episode, then left undeleted in the clean baseline.
#[must_use]
pub fn tests_api(present: bool) -> String {
    if !present {
        return String::new();
    }
    "use lumen::store::Store;\n\n\
     #[test]\nfn query_returns_the_window() {\n\
     \x20   let mut store = Store::default();\n\
     \x20   store.append(&lumen::core::ramp(10));\n\
     \x20   let rows = lumen::api::query(&store, 2_000, 4_000);\n\
     \x20   assert_eq!(rows.len(), 3);\n}\n\n\
     #[test]\nfn query_outside_everything_is_empty() {\n\
     \x20   let store = Store::default();\n\
     \x20   assert!(lumen::api::query(&store, 0, 1).is_empty());\n}\n"
        .to_owned()
}

/// The CI workflow, with or without the bench job an unrelated commit adds.
#[must_use]
pub fn ci_yml(with_new_job: bool) -> String {
    let mut out = String::from(
        "name: lumen\non:\n  pull_request:\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n\
         \x20 - uses: actions/checkout@v4\n\x20 - run: cargo test\n",
    );
    if with_new_job {
        out.push_str(
            "  bench:\n    runs-on: ubuntu-latest\n    steps:\n\
                      \x20 - uses: actions/checkout@v4\n\x20 - run: cargo bench\n",
        );
    }
    out
}

/// `web/package.json`.
#[must_use]
pub fn package_json(express: &str, extra_dev: bool) -> String {
    let dev = if extra_dev {
        ",\n\x20   \"prettier\": \"3.6.2\""
    } else {
        ""
    };
    format!(
        "{{\n  \"name\": \"lumen-web\",\n  \"version\": \"1.2.0\",\n  \"private\": true,\n\
         \x20 \"dependencies\": {{\n\x20   \"express\": \"{express}\",\n\x20   \"chart.js\": \"4.4.9\"\n\x20 }},\n\
         \x20 \"devDependencies\": {{\n\x20   \"jest\": \"29.7.0\"{dev}\n\x20 }}\n}}\n"
    )
}

/// The lockfile for `package_json`, with one transitive pin so a transitive-only bump has something to move.
#[must_use]
pub fn package_lock(express: &str, body_parser: &str) -> String {
    format!(
        "{{\n  \"name\": \"lumen-web\",\n  \"version\": \"1.2.0\",\n  \"lockfileVersion\": 3,\n\
         \x20 \"packages\": {{\n\
         \x20   \"node_modules/express\": {{\n\x20     \"version\": \"{express}\"\n\x20 }},\n\
         \x20   \"node_modules/body-parser\": {{\n\x20     \"version\": \"{body_parser}\"\n\x20 }},\n\
         \x20   \"node_modules/chart.js\": {{\n\x20     \"version\": \"4.4.9\"\n\x20 }}\n\x20 }}\n}}\n"
    )
}

/// The reporter's requirements, unpinned or pinned — the Python half of a dependency bump.
#[must_use]
pub fn requirements(pinned: bool) -> String {
    if pinned {
        "pandas==2.3.3\nnumpy==2.2.6\npyarrow==20.0.0\n"
    } else {
        "pandas>=2.0\nnumpy>=2.0\npyarrow>=18.0\n"
    }
    .to_owned()
}

/// `services/reporter/report.py`, so the Python half of the repository is a file and not a directory name.
#[must_use]
pub fn report_py(round: u32) -> String {
    format!(
        "import pandas as pd\n\n\
         def nightly(path: str) -> pd.DataFrame:\n\
         \x20   frames = pd.read_parquet(path)\n\
         \x20   out = frames.groupby(\"bucket\").mean()\n\
         \x20   {}\n\
         \x20   return out\n",
        if round == 0 {
            "out.to_parquet(path + \".nightly\")"
        } else {
            "out.to_parquet(path + \".nightly.parquet\")"
        }
    )
}

/// A minified JavaScript bundle: one deterministic line, `want` bytes long, with the header a real bundle
/// carries. Deterministic because it is a repetition of a fixed string, and because the scenario whose
/// claim is "a 600 KB generated file appeared" has to mean it.
#[must_use]
pub fn bundle_min(want: usize) -> String {
    let header = "/*! lumen-web bundle; @generated by esbuild; do not edit by hand */\n";
    let unit = "function n(t){return t.map(function(x){return x*2})}var e={};";
    let mut out = String::from(header);
    while out.len() < want.saturating_sub(64) {
        out.push_str(unit);
    }
    out.push_str("//# sourceMappingURL=bundle.min.js.map\n");
    out
}

/// A large deterministic JSON document, shaped like an OpenAPI file: real enough that a generated-file
/// detector has a `@generated` marker to find, and big enough to cross a cap.
#[must_use]
pub fn openapi_json(records: usize) -> String {
    let mut out =
        String::from("{\n  \"openapi\": \"3.1.0\",\n  \"x-generated\": true,\n  \"paths\": {\n");
    for index in 0..records {
        out.push_str(&format!(
            "    \"/v1/series/{index}\": {{\n      \"get\": {{\n        \"operationId\": \"getSeries{index}\",\n\
             \x20       \x20 \"summary\": \"read one series bucket\"\n      }}\n    }}"
        ));
        if index + 1 < records {
            out.push_str(",\n");
        }
    }
    out.push_str("\n  }\n}\n");
    out
}

/// A deterministic binary blob of `want` bytes: no NUL-free run is longer than 15 bytes, so every
/// "is this binary?" test says yes for the same reason on every platform.
#[must_use]
pub fn binary_blob(want: usize) -> Vec<u8> {
    let mut out = Vec::with_capacity(want);
    let mut state: u32 = 0x1234_5678;
    while out.len() < want {
        // xorshift32: small, fixed, and the same on every target.
        state ^= state << 13;
        state ^= state >> 17;
        state ^= state << 5;
        for byte in state.to_le_bytes() {
            out.push(byte);
            if out.len() >= want {
                break;
            }
        }
        if out.len() % 17 == 0 && out.len() < want {
            out.push(0);
        }
    }
    out
}

/// `src/scheduler.rs`, round by round. Round `n` changes two lines inside `drain` — the same lines every
/// time, which is what makes the churn claim checkable rather than a story.
#[must_use]
pub fn scheduler_rs(round: u32) -> String {
    let window = 4 + round * 2;
    let spin = if round.is_multiple_of(2) {
        "continue"
    } else {
        "break"
    };
    format!(
        "use crate::queue::Queue;\n\n\
         /// The scheduler: drain the queue in bounded windows.\n\
         pub struct Scheduler {{\n    pub window: u32,\n}}\n\n\
         impl Scheduler {{\n\
         \x20   pub fn new() -> Self {{\n\
         \x20       Self {{ window: {window} }}\n\
         \x20   }}\n\n\
         \x20   /// Drain up to `self.window` jobs. Round {round} of the same argument about what happens\n\
         \x20   /// when the queue is not empty at the window's edge.\n\
         \x20   pub fn drain(&self, queue: &mut Queue) -> u32 {{\n\
         \x20       let mut done = 0;\n\
         \x20       while done < self.window {{\n\
         \x20           let Some(job) = queue.pop() else {{\n\
         \x20               {spin};\n\
         \x20           }};\n\
         \x20           job.run();\n\
         \x20           done += 1;\n\
         \x20           queue.requeue(job.after());\n\
         \x20       }}\n\
         \x20       done\n\
         \x20   }}\n}}\n\n\
         impl Default for Scheduler {{\n\
         \x20   fn default() -> Self {{\n\
         \x20       Self::new()\n\
         \x20   }}\n}}\n"
    )
}

/// `src/queue.rs`, edited in the same region as `scheduler_rs` by the same rounds.
#[must_use]
pub fn queue_rs(round: u32) -> String {
    let capacity = 8 + round * 4;
    format!(
        "/// A job the scheduler can run.\npub struct Job {{\n    pub id: u32,\n}}\n\n\
         impl Job {{\n\
         \x20   pub fn run(&self) {{\n\
         \x20       let _ = self.id;\n\
         \x20   }}\n\n\
         \x20   pub fn after(&self) -> Option<Job> {{\n\
         \x20       None\n\
         \x20   }}\n}}\n\n\
         /// A bounded queue; the bound is the argument every round of the churn has been about.\n\
         #[derive(Default)]\npub struct Queue {{\n\
         \x20   items: Vec<Job>,\n\
         \x20   pub capacity: u32,\n}}\n\n\
         impl Queue {{\n\
         \x20   pub fn new() -> Self {{\n\
         \x20       Self {{ items: Vec::new(), capacity: {capacity} }}\n\
         \x20   }}\n\n\
         \x20   pub fn pop(&mut self) -> Option<Job> {{\n\
         \x20       self.items.pop()\n\
         \x20   }}\n\n\
         \x20   pub fn requeue(&mut self, job: Option<Job>) {{\n\
         \x20       if let Some(job) = job {{\n\
         \x20           if self.items.len() < self.capacity as usize {{\n\
         \x20               self.items.push(job);\n\
         \x20           }}\n\
         \x20       }}\n\
         \x20   }}\n}}\n"
    )
}

