/// The same file, reformatted: indentation halved, trailing whitespace gone, blank lines collapsed.
///
/// No token moves, which is the entire point — `verify` re-checks the claim by stripping whitespace from both
/// sides and comparing, so a scenario that passed a real change through here would fail its own ground truth
/// rather than quietly teaching the noise detector to call a fix noise.
#[must_use]
pub fn reformatted(text: &str) -> String {
    let mut out: Vec<String> = Vec::new();
    for line in text.lines() {
        let indent = line.len() - line.trim_start().len();
        let trimmed = line.trim();
        if trimmed.is_empty() {
            if out.last().is_some_and(|last| !last.is_empty()) {
                out.push(String::new());
            }
            continue;
        }
        out.push(format!("{}\x20{trimmed}", " ".repeat(indent / 2)));
    }
    let mut body = out.join("\n");
    if !body.ends_with('\n') {
        body.push('\n');
    }
    body
}

/// The same file with its top-level items in reverse order and nothing else changed.
///
/// A reorder is the change a whitespace-only detector must *not* catch: the bytes differ beyond whitespace,
/// the token multiset is identical, and the behaviour is unchanged. `reformat_only` needs both kinds, or the
/// detector that only checks whitespace looks perfect.
#[must_use]
pub fn reordered(text: &str) -> String {
    let blocks: Vec<&str> = text.trim_end().split("\n\n").collect();
    let mut body: Vec<&str> = blocks[1..].to_vec();
    body.reverse();
    let mut out = String::from(blocks[0]);
    for block in body {
        out.push_str("\n\n");
        out.push_str(block);
    }
    out.push('\n');
    out
}

/// The import table: the same shape for every `n`, rotated by it.
///
/// `ten_k_commits` writes this file ten thousand times. A file that *grew* on every commit would make the
/// fixture's cost quadratic in the commit count — every retained tree state would carry the whole file again —
/// and a fixture that costs two gigabytes to build is not a fixture, it is an outage. Fixed-size content with
/// rotating values keeps the commits real (each one changes lines in a file the next commit changes again) and
/// keeps the cost per commit constant.
#[must_use]
pub fn imported_rs(n: usize) -> String {
    let mut out = String::from(
        "//! Everything the import brought in, in a fixed number of slots.\n\
         //! Each batch retunes one coefficient; nothing here grows.\n",
    );
    for slot in 0..16 {
        out.push_str(&format!(
            "pub fn slot_{slot}() -> u32 {{ (({n} * {slot}) % 97) as u32 }}\n"
        ));
    }
    out
}
